package com.wanfo.bi.service;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.wanfo.bi.domain.BiDashboardDO;
class DashboardScreenTest {
 DashboardService.Panel text(String key,int x,int y,int w,int h){return new DashboardService.Panel(key,null,"Text",x,y,w,h,"text",null,new DashboardContent.Content("Hello",null));}
 DashboardService.Definition doc(List<DashboardService.Panel> panels){return new DashboardService.Definition(1,"Screen",panels,"screen","absolute",null,null,new DashboardPresentation.Scene(1920,1080,"contain"));}
 @Test void sceneBoundsAndModes(){assertEquals(1920,DashboardPresentation.scene("screen",new DashboardPresentation.Scene(1920,1080,"contain")).width());assertThrows(IllegalArgumentException.class,()->DashboardPresentation.scene("screen",null));assertThrows(IllegalArgumentException.class,()->DashboardPresentation.scene("screen",new DashboardPresentation.Scene(100,1080,"contain")));assertThrows(IllegalArgumentException.class,()->DashboardPresentation.scene("dashboard",new DashboardPresentation.Scene(1920,1080,"contain")));}
 @Test void carrierPairMustMatch(){assertDoesNotThrow(()->DashboardPresentation.carrier("screen","absolute"));assertThrows(IllegalArgumentException.class,()->DashboardPresentation.carrier("screen","grid"));assertThrows(IllegalArgumentException.class,()->DashboardPresentation.carrier("dashboard","absolute"));}
 @Test void freePanelsMayOverlapAndOrderPersists(){var f=new DashboardTest();doAnswer(c->{((BiDashboardDO)c.getArgument(0)).setId(9L);return 1;}).when(f.mapper).insert(any());f.service.create(new DashboardService.SaveRequest(null,doc(List.of(text("back",20,20,500,300),text("front",30,30,300,200)))));var capture=org.mockito.ArgumentCaptor.forClass(BiDashboardDO.class);verify(f.mapper).insert(capture.capture());var stored=f.json.readValue(capture.getValue().getDefinitionJson(),DashboardService.Definition.class);assertEquals("screen",stored.kind());assertEquals("front",stored.panels().get(1).key());assertEquals(1920,stored.scene().width());}
 @Test void freeBoundsRejectOverflowAndTinyPanels(){var f=new DashboardTest();for(var p:List.of(text("x",1900,0,100,100),text("x",0,0,19,100),text("x",0,Integer.MAX_VALUE,100,100)))assertThrows(IllegalArgumentException.class,()->f.service.create(new DashboardService.SaveRequest(null,doc(List.of(p)))));verify(f.mapper,never()).insert(any());}
 @Test void publicationKeepsSceneAndAuthorPreview(){var f=new DashboardTest();var row=f.stored(false);row.setDefinitionJson(f.json.writeValueAsString(doc(List.of(text("a",100,100,300,200)))));when(f.mapper.publish(eq(7L),eq(2),eq(3),anyString(),eq("author"))).thenReturn(1);f.service.publish(7L,2);var capture=org.mockito.ArgumentCaptor.forClass(String.class);verify(f.mapper).publish(eq(7L),eq(2),eq(3),capture.capture(),eq("author"));var pub=f.json.readValue(capture.getValue(),DashboardService.Publication.class);assertEquals("screen",pub.kind());assertEquals("absolute",pub.layout());assertEquals(1080,pub.scene().height());}
 @Test void refreshDefaultsAndBounds(){
   assertEquals(0,DashboardPresentation.scene("screen",new DashboardPresentation.Scene(640,480,"contain")).refreshSeconds());
   for(int seconds:List.of(0,10,60,3600))assertEquals(seconds,DashboardPresentation.scene("screen",new DashboardPresentation.Scene(640,480,"contain",seconds)).refreshSeconds());
   for(int seconds:List.of(-1,1,9,3601))assertThrows(IllegalArgumentException.class,()->DashboardPresentation.scene("screen",new DashboardPresentation.Scene(640,480,"contain",seconds)));
 }
 @Test void oldSceneJsonDefaultsOff(){var f=new DashboardTest();var old=f.json.readValue("{\"width\":640,\"height\":480,\"fit\":\"contain\"}",DashboardPresentation.Scene.class);assertEquals(0,DashboardPresentation.scene("screen",old).refreshSeconds());}
 DashboardService.Panel grouped(String key,String group){return new DashboardService.Panel(key,null,"Text",20,20,100,100,"text",null,new DashboardContent.Content("Hello",null),false,null,group);}
 @Test void groupsRoundtripAndFreeze(){var f=new DashboardTest();var d=doc(List.of(grouped("a","g"),grouped("b","g")));var row=f.stored(false);row.setDefinitionJson(f.json.writeValueAsString(d));when(f.mapper.publish(eq(7L),eq(2),eq(3),anyString(),eq("author"))).thenReturn(1);f.service.publish(7L,2);var capture=org.mockito.ArgumentCaptor.forClass(String.class);verify(f.mapper).publish(eq(7L),eq(2),eq(3),capture.capture(),eq("author"));var pub=f.json.readValue(capture.getValue(),DashboardService.Publication.class);assertEquals("g",pub.panels().get(0).layout().groupKey());assertEquals("g",pub.panels().get(1).layout().groupKey());}
 @Test void invalidAndSingletonGroupsReject(){var f=new DashboardTest();for(var d:List.of(doc(List.of(grouped("a","g"))),doc(List.of(grouped("a","bad key"),grouped("b","bad key"))),new DashboardService.Definition(1,"Grid",List.of(grouped("a","g"),grouped("b","g")))))assertThrows(IllegalArgumentException.class,()->f.service.create(new DashboardService.SaveRequest(null,d)));verify(f.mapper,never()).insert(any());}
 DashboardService.Panel hiddenChart(String key,String group,boolean hidden){return new DashboardService.Panel(key,4L,"Hidden",20,20,100,100,"chart",null,null,false,null,group,hidden);}
 @Test void hiddenManifestAndDirectQueryAreDenied(){var f=new DashboardTest();var row=f.stored(true);var hidden=hiddenChart("secret",null,true);row.setPublishedJson(f.json.writeValueAsString(new DashboardService.Publication(1,"Screen",List.of(new DashboardService.PublishedPanel(hidden,f.chart()),new DashboardService.PublishedPanel(text("visible",0,0,100,100),null)),"screen","absolute",null,null,new DashboardPresentation.Scene(640,480,"contain"))));assertFalse(f.json.writeValueAsString(f.service.view(7L)).contains("secret"));assertEquals(403,assertThrows(com.wanfo.bi.security.BiAccessException.class,()->f.service.panelData(7L,"secret",1)).getCode());verifyNoInteractions(f.queries);}
 @Test void hiddenAuthorPreviewDoesNotQuery() throws Exception {var f=new DashboardTest();when(f.charts.exportForDashboard(4L)).thenReturn(f.chart());var result=f.service.preview(null,new DashboardService.PreviewRequest(null,doc(List.of(hiddenChart("secret",null,true),text("visible",0,0,100,100))),Map.of()));assertEquals(Map.of(),result.get("payloads"));verifyNoInteractions(f.queries);}
 @Test void mixedVisibilityAndGridHiddenReject(){var f=new DashboardTest();for(var d:List.of(doc(List.of(hiddenChart("a","g",true),hiddenChart("b","g",false))),new DashboardService.Definition(1,"Grid",List.of(hiddenChart("a",null,true)))))assertThrows(IllegalArgumentException.class,()->f.service.create(new DashboardService.SaveRequest(null,d)));verify(f.mapper,never()).insert(any());}
 @Test void hiddenBindingsAndAllHiddenPublicationReject(){var f=new DashboardTest();var hidden=hiddenChart("a",null,true);var settings=new DashboardInteraction.Settings(List.of(new DashboardInteraction.Control("city","City","text",null,List.of(new DashboardInteraction.Target("a","city")))),null);var d=new DashboardService.Definition(1,"Screen",List.of(hidden),"screen","absolute",null,settings,new DashboardPresentation.Scene(640,480,"contain"));assertThrows(IllegalArgumentException.class,()->f.service.create(new DashboardService.SaveRequest(null,d)));var row=f.stored(false);row.setDefinitionJson(f.json.writeValueAsString(doc(List.of(hidden))));assertThrows(IllegalArgumentException.class,()->f.service.publish(7L,2));verify(f.mapper,never()).publish(any(),anyInt(),anyInt(),anyString(),anyString());}
 @Test void decorationDefaultsAndBounds(){var d=DashboardContent.normalize("border",null).decoration();assertEquals("#38BDF8",d.color());assertEquals(2,d.stroke());for(var bad:List.of(new DashboardContent.Decoration("url(x)",2,"solid",8,"horizontal"),new DashboardContent.Decoration("#123456",13,"solid",8,"horizontal"),new DashboardContent.Decoration("#123456",2,"double",8,"horizontal"),new DashboardContent.Decoration("#123456",2,"solid",81,"horizontal"),new DashboardContent.Decoration("#123456",2,"solid",8,"script")))assertThrows(IllegalArgumentException.class,()->DashboardContent.normalize("line",new DashboardContent.Content(null,null,bad)));}
 @Test void decorationPayloadCannotMixContent(){assertThrows(IllegalArgumentException.class,()->DashboardContent.normalize("border",new DashboardContent.Content("script",null)));assertThrows(IllegalArgumentException.class,()->DashboardContent.normalize("text",new DashboardContent.Content("ok",null,new DashboardContent.Decoration(null,null,null,null,null))));}
 @Test void decorationOnlyScreenAndPreviewNeverQueries() throws Exception {var f=new DashboardTest();var p=new DashboardService.Panel("frame",null,"Border",0,0,300,200,"border",null,null);assertThrows(IllegalArgumentException.class,()->f.service.create(new DashboardService.SaveRequest(null,new DashboardService.Definition(1,"Grid",List.of(p)))));var preview=f.service.preview(null,new DashboardService.PreviewRequest(null,doc(List.of(p)),Map.of()));assertEquals(Map.of(),preview.get("payloads"));verifyNoInteractions(f.queries);}
 @Test void publicationFreezesDecoration(){var f=new DashboardTest();var content=new DashboardContent.Content(null,null,new DashboardContent.Decoration("#FF8800",4,"dashed",12,"vertical"));var p=new DashboardService.Panel("frame",null,"Frame",0,0,300,200,"border",null,content);var row=f.stored(false);row.setDefinitionJson(f.json.writeValueAsString(doc(List.of(p))));when(f.mapper.publish(eq(7L),eq(2),eq(3),anyString(),eq("author"))).thenReturn(1);f.service.publish(7L,2);var capture=org.mockito.ArgumentCaptor.forClass(String.class);verify(f.mapper).publish(eq(7L),eq(2),eq(3),capture.capture(),eq("author"));var pub=f.json.readValue(capture.getValue(),DashboardService.Publication.class);assertEquals("#FF8800",pub.panels().get(0).layout().content().decoration().color());assertEquals("dashed",pub.panels().get(0).layout().content().decoration().pattern());}
}
